/**
 * Chart.js Local Minified Version
 * Versão local para evitar dependência de CDN
 */

// Placeholder para Chart.js local
// Em produção, baixar Chart.js e colocar aqui
// Por enquanto, fallback para CDN com cache

if (typeof Chart === 'undefined') {
    // Carregar Chart.js do CDN com cache
    const script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.js';
    script.crossOrigin = 'anonymous';
    script.integrity = 'sha384-...'; // Adicionar hash de integridade
    script.onload = function() {
        console.log('Chart.js carregado do CDN');
        if (window.initCharts) window.initCharts();
    };
    script.onerror = function() {
        console.warn('Falha ao carregar Chart.js, usando fallback');
        // Implementar fallback simples
        window.Chart = {
            register: () => {},
            Chart: function() {
                return {
                    update: () => {},
                    destroy: () => {}
                };
            }
        };
    };
    document.head.appendChild(script);
}